    for (const r of allExisting.results) {
      existingMap.set(`${r.ngay}|${r.so_ct}|${r.ma_hang}`, r);
    }
    const records = [];
    let parseSkipped = 0;
    for (const row of dataRows) {
      const record = {};
      for (const m of COL_MAP) {
        let val = row[m.idx];
        if (m.db === "ngay" && typeof val === "number") {
          const d = new Date((val - 25569) * 86400 * 1e3);
          const dd = String(d.getDate()).padStart(2, "0");
          const mm = String(d.getMonth() + 1).padStart(2, "0");
          const yyyy = d.getFullYear();
          val = `${dd}/${mm}/${yyyy}`;
        }
        if (["sl_ban", "don_gia", "doanh_so", "ck", "sl_tra", "gt_tra", "gt_giam", "thue"].includes(m.db)) {
          val = typeof val === "number" ? val : 0;
        } else {
          val = val !== void 0 && val !== null ? String(val).trim() : "";
        }
        record[m.db] = val;
      }
      if (!record.ma_hang) {
        parseSkipped++;
        continue;
      }
      records.push(record);
    }
    const colNames = COL_MAP.map((m) => m.db).join(", ");
    const placeholders = COL_MAP.map(() => "?").join(", ");
    const setClause = COL_MAP.map((m) => `${m.db} = ?`).join(", ");
    const insertStmts = [];
    const updateStmts = [];
    let skipped = parseSkipped;
    let imported = 0;
    for (const record of records) {
      const key = `${record.ngay}|${record.so_ct}|${record.ma_hang}`;
      const existing = existingMap.get(key);
      if (existing) {
        let changed = false;
        for (const m of COL_MAP) {
          if (String(existing[m.db] ?? "") !== String(record[m.db] ?? "")) {
            changed = true;
            break;
          }
        }
        if (changed) {
          updateStmts.push(
            c.env.DB.prepare(`UPDATE so_chi_tiet_ban_hang SET ${setClause} WHERE id = ?`).bind(...COL_MAP.map((m) => record[m.db]), existing.id)
          );
          imported++;
        } else {
          skipped++;
        }
      } else {
        insertStmts.push(
          c.env.DB.prepare(`INSERT INTO so_chi_tiet_ban_hang (${colNames}) VALUES (${placeholders})`).bind(...COL_MAP.map((m) => record[m.db]))
        );
        imported++;
      }
    }
    const BATCH = 100;
    for (let i = 0; i < insertStmts.length; i += BATCH) {
      await c.env.DB.batch(insertStmts.slice(i, i + BATCH));
    }
    for (let i = 0; i < updateStmts.length; i += BATCH) {
      await c.env.DB.batch(updateStmts.slice(i, i + BATCH));
    }
    const soKhachMoi = await themKhachMoiVaoBangCK(c.env.DB);
    return c.json({
      success: true,
      total: records.length,
      imported,
      skipped,
      so_khach_moi: soKhachMoi,
      message: `Import ${imported} d\xF2ng th\xE0nh c\xF4ng${skipped ? `, b\u1ECF qua ${skipped} d\xF2ng` : ""}. T\u1EF1 th\xEAm ${soKhachMoi} kh\xE1ch m\u1EDBi v\xE0o b\u1EA3ng chi\u1EBFt kh\u1EA5u.`
    });
