app3.get("/kiem-tra-bang-tinh-gia", async (c) => {
  try {
    const db = c.env.DB;
    const page = parseInt(c.req.query("page") || "1");
    const limit = Math.min(parseInt(c.req.query("limit") || "500"), 2e3);
    const offset = (page - 1) * limit;
    const mod = c.req.query("module") || "";
    const diffFilter = c.req.query("diff") || "";
    const results = [];
    let total = 0;
    const modules = mod ? [mod] : Object.keys(MODULE_KIEM_TRA);
    for (const module of modules) {
      const cfg = MODULE_KIEM_TRA[module];
      if (!cfg)
        continue;
      const labelExpr = cfg.labelCols.map((c2) => `t.${c2}`).join(" || ' ' || ");
      const { results: rows } = await db.prepare(
        `SELECT t.id, t.ma_sp, t.ten_sp, t.${cfg.priceCol} AS tong_gia, m.gia_goc AS gia_goc_misa,
                ${labelExpr} AS mo_ta
         FROM ${cfg.table} t
         LEFT JOIN ma_misa m ON t.ma_sp = m.ma_sp
         WHERE t.ma_sp IS NOT NULL AND t.ma_sp != ''
         ORDER BY t.ma_sp
         LIMIT ? OFFSET ?`
      ).bind(limit, offset).all();
      for (const row of rows) {
        const t = row.tong_gia;
        const g = row.gia_goc_misa;
        const diff = t != null && g != null ? t - g : null;
        const pct = t != null && g != null && g > 0 ? Math.round((t - g) / g * 100) : null;
        if (diffFilter === "bang" && diff !== 0)
          continue;
        if (diffFilter === "cao" && (diff == null || diff <= 0))
          continue;
        if (diffFilter === "thap" && (diff == null || diff >= 0))
          continue;
        if (diffFilter === "khong" && g != null)
          continue;
        results.push({
          module,
          id: row.id,
          ma_sp: row.ma_sp,
          ten_sp: row.ten_sp,
          mo_ta: row.mo_ta,
          tong_gia: t,
          gia_goc_misa: g,
          diff,
          pct
        });
        total++;
      }
    }
    return c.json({
      data: results.slice(0, limit),
      total,
      page,
      limit,
      total_pages: Math.ceil(total / limit)
    });
  } catch (e) {
    return c.json({ error: e.message }, 500);
  }
});
